# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">قِصَّةُ لُقْمَانَ الْحَكِيمِ — HZ. LOKMAN VE HİKMET KAVRAMI</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Temel Arapça Kelime ve Kavramlar</text>\n  <text x="40" y="96" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">الْحِكْمَةُ (el-Hikmetü):</tspan> Hikmet, derin bilgi</text>\n  <text x="40" y="120" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">الْمَوْعِظَةُ / النَّصِيحَةُ:</tspan> Öğüt, nasihat</text>\n  <text x="40" y="144" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">يَا بُنَيَّ (Yâ büneyye):</tspan> Ey oğulcuğum / yavrum</text>\n  <text x="40" y="168" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">الشِّرْكُ (eş-Şirkü):</tspan> Allah\'a ortak koşmak</text>\n  <text x="40" y="192" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">ظُلْمٌ عَظِيمٌ (Zulmün azîm):</tspan> Büyük bir zulüm</text>\n  <text x="40" y="216" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">بِرُّ الْوَالِدَيْنِ:</tspan> Anne babaya iyilik ve ihsan</text>\n\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Lokman Suresi 12-13. Ayet İfadeleri</text>\n  <rect x="375" y="84" width="285" height="65" rx="6" fill="#ffffff" stroke="#4ade80" stroke-width="1.5"/>\n  <text x="517" y="106" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">آتَيْنَا لُقْمَانَ الْحِكْمَةَ أَنِ اشْكُرْ لِلَّهِ</text>\n  <text x="517" y="130" text-anchor="middle" font-size="11" fill="#14532d">"Lokman\'a: Allah\'a şükret! diye hikmet verdik."</text>\n  <rect x="375" y="160" width="285" height="65" rx="6" fill="#ffffff" stroke="#4ade80" stroke-width="1.5"/>\n  <text x="517" y="182" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">يَا بُنَيَّ لَا تُشْرِكْ بِاللَّهِ</text>\n  <text x="517" y="206" text-anchor="middle" font-size="11" fill="#14532d">"Yavrucuğum! Allah\'a ortak koşma (şirkten sakın)."</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">وَصَايَا لُقْمَانَ لِابْنِهِ — EMİR VE NEHİY ÖĞÜTLERİ TABLOSU</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">الأَوَامِرُ (Emredilen Davranışlar)</text>\n  <text x="40" y="96" font-size="12" fill="#14532d">• <tspan font-weight="bold">اشْكُرْ لِلَّهِ:</tspan> Allah\'a şükret!</text>\n  <text x="40" y="120" font-size="12" fill="#14532d">• <tspan font-weight="bold">أَقِمِ الصَّلَاةَ:</tspan> Namazı dosdoğru kıl!</text>\n  <text x="40" y="144" font-size="12" fill="#14532d">• <tspan font-weight="bold">أْمُرْ بِالْمَعْرُوفِ:</tspan> İyiliği (marufu) emret!</text>\n  <text x="40" y="168" font-size="12" fill="#14532d">• <tspan font-weight="bold">انْهَ عَنِ الْمُنْكَرِ:</tspan> Kötülükten (münkerden) vazgeçir!</text>\n  <text x="40" y="192" font-size="12" fill="#14532d">• <tspan font-weight="bold">اصْبِرْ عَلَى مَا أَصَابَكَ:</tspan> Başına gelene sabret!</text>\n  <text x="40" y="216" font-size="12" fill="#14532d">• <tspan font-weight="bold">اقْصِدْ فِي مَشْيِكَ / اغْضُضْ مِنْ صَوْتِكَ:</tspan> Ölçülü ol!</text>\n\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#991b1b">النَّوَاهِي (Yasaklanan Davranışlar)</text>\n  <rect x="375" y="84" width="285" height="44" rx="6" fill="#ffffff" stroke="#f87171" stroke-width="1.5"/>\n  <text x="517" y="103" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">1. لَا تُشْرِكْ بِاللَّهِ (Şirk koşma!)</text>\n  <text x="517" y="120" text-anchor="middle" font-size="11" fill="#7f1d1d">İnançta tevhidi koruma emri</text>\n\n  <rect x="375" y="136" width="285" height="44" rx="6" fill="#ffffff" stroke="#f87171" stroke-width="1.5"/>\n  <text x="517" y="155" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">2. لَا تُصَعِّرْ خَدَّكَ لِلنَّاسِ (Yüz çevirme!)</text>\n  <text x="517" y="172" text-anchor="middle" font-size="11" fill="#7f1d1d">İnsanları küçümsememe ve tevazu</text>\n\n  <rect x="375" y="188" width="285" height="44" rx="6" fill="#ffffff" stroke="#f87171" stroke-width="1.5"/>\n  <text x="517" y="207" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">3. لَا تَمْشِ فِي الْأَرْضِ مَرَحًا (Böbürlenerek yürüme!)</text>\n  <text x="517" y="224" text-anchor="middle" font-size="11" fill="#7f1d1d">Kibir ve gösterişten kaçınma</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">الْفِعْلُ الْمُجَرَّدُ وَالْمَزِيدُ فِي قِصَّةِ لُقْمَانَ</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">الْفِعْلُ الْمُجَرَّدُ (Sülâsî Mücerred - 3 Harfli)</text>\n  <text x="40" y="96" font-size="12" fill="#78350f">• <tspan font-weight="bold">شَكَرَ - يَشْكُرُ - اشْكُرْ:</tspan> Şükretti / Şükret</text>\n  <text x="40" y="122" font-size="12" fill="#78350f">• <tspan font-weight="bold">وَعَظَ - يَعِظُ - عِظْ:</tspan> Öğüt verdi / Öğüt ver</text>\n  <text x="40" y="148" font-size="12" fill="#78350f">• <tspan font-weight="bold">صَبَرَ - يَصْبِرُ - اصْبِرْ:</tspan> Sabretti / Sabret</text>\n  <text x="40" y="174" font-size="12" fill="#78350f">• <tspan font-weight="bold">قَصَدَ - يَقْصِدُ - اقْصِدْ:</tspan> Ölçülü oldu / Ölçülü ol</text>\n  <text x="40" y="200" font-size="12" fill="#78350f">• <tspan font-weight="bold">غَضَّ - يَغُضُّ - اغْضُضْ:</tspan> Kıstı, alçalttı (Mudâaf)</text>\n  <text x="40" y="224" font-size="11" font-weight="bold" fill="#b45309">Tamamı 3 asli kök harfinden oluşur.</text>\n\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#ede9fe" stroke="#7c3aed" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#5b21b6">الْفِعْلُ الْمَزِيدُ (Sülâsî Mezîd - Ek Almış)</text>\n  <text x="375" y="96" font-size="12" fill="#4c1d95">• <tspan font-weight="bold">أَشْرَكَ (ش-ر-ك + أ):</tspan> Ortak koştu (İf\'âl babı)</text>\n  <text x="375" y="122" font-size="12" fill="#4c1d95">• <tspan font-weight="bold">أَقَامَ (ق-و-م + أ):</tspan> Dosdoğru kıldı (İf\'âl babı)</text>\n  <text x="375" y="148" font-size="12" fill="#4c1d95">• <tspan font-weight="bold">أَوْصَى (و-ص-ي + أ):</tspan> Tavsiye etti (İf\'âl babı)</text>\n  <text x="375" y="174" font-size="12" fill="#4c1d95">• <tspan font-weight="bold">صَعَّرَ (ص-ع-ر + تضعيف):</tspan> Yüz çevirdi (Tef\'îl)</text>\n  <text x="375" y="200" font-size="12" fill="#4c1d95">• <tspan font-weight="bold">اخْتَالَ (خ-ي-ل + ا، ت):</tspan> Kibirlendi (İfti\'âl)</text>\n  <text x="375" y="224" font-size="11" font-weight="bold" fill="#6d28d9">Kök harflerine 1 veya 2 harf eklenmiştir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
